('obs_claim_ng10_c01',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='nadir-godrej' LIMIT 1),'current_role','As of July 26, 2026, Godrej is Chairperson of Godrej Industries Group and Chairman and Managing Director of Godrej Industries Limited.','formal_role','primary_record','unreviewed',NULL,'Current chair and managing director, with an as-of date.','No sole ownership, permanent authority, subsidiary ownership or identity with the legal entities.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_ng10_c02',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='nadir-godrej' LIMIT 1),'current_role','Godrej is Chairman and Non-Executive Director of Godrej Agrovet within a separately disclosed board and executive structure.','formal_role','primary_record','unreviewed',NULL,'Chairman of Godrej Agrovet within multi-person governance.','No sole operational control, labor, strategy, ownership or company-performance attribution.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_ng10_c03',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='nadir-godrej' LIMIT 1),'succession','A primary April 2026 announcement fixes a planned August 2026 retirement and specified board exits and records his Astec exit effective April 13, 2026.','time_bounded_authority','primary_record','unreviewed',NULL,'Planned future role endings and one completed Astec exit.','Do not describe future exits as completed or infer forced removal, dispute, incapacity or motive.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_ng10_c04',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='nadir-godrej' LIMIT 1),'ownership_realignment','The 2024 family agreement separated Godrej Industries Group and Godrej Enterprises Group under distinct leadership and company structures.','institutional_boundary','corroborated','unreviewed',NULL,'A disclosed family ownership and operating realignment into distinct groups.','No pre-split personal ownership, sole-causation or ownership of Godrej Enterprises Group.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_ng10_c05',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='nadir-godrej' LIMIT 1),'trust_relationship','Shareholding filings name Godrej as one of multiple trustees for holder-specific promoter-group trusts.','ownership_boundary','primary_record','unreviewed',NULL,'Named co-trustee in specific promoter-group holder records.','Trustee status is not personal beneficial ownership; do not aggregate trust shares as his personal stake, wealth or vote.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_ng10_c06',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='nadir-godrej' LIMIT 1),'role_history','Godrej has served within the group since 1977 and formally succeeded Adi Godrej as GIL Chairman and Managing Director effective October 1, 2021.','formal_role','primary_record','unreviewed',NULL,'Long-tenured executive and formal 2021 successor.','No founder, sole builder, owner, uninterrupted identical authority or isolated performance claim.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_ng10_c07',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='nadir-godrej' LIMIT 1),'co_invention','Patent record IN185675B names Nadir Godrej with Keki Mistry and Brahmanand Vyas as inventors and Godrej Agrovet as original assignee.','distributed_invention','primary_record','unreviewed',NULL,'Named co-inventor on the identified patent record.','No sole inventorship, current validity, freedom to operate, personal IP ownership or licensing-revenue claim.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_ng10_c08',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='nadir-godrej' LIMIT 1),'creative_role','Godrej publicly writes and performs poetry, including in business and agricultural settings.','creative_role','corroborated','unreviewed',NULL,'Poet and public performer of his own verse.','No complete bibliography, publishing-rights, recording-rights, sales or measured audience-impact claim.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_ng10_c09',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='nadir-godrej' LIMIT 1),'metric_boundary','Listed-company results, market values, promoter holdings and group scale are company- or holder-specific measures.','financial_boundary','primary_record','unreviewed',NULL,'Report each measure with its entity, holder and date.','Do not convert company or trust figures into personal income, wealth, liquidity, enterprise value or isolated leadership performance.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_ng10_c10',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='nadir-godrej' LIMIT 1),'claim_restriction','No reviewed public record establishes complete beneficial ownership, trust instruments, voting arrangements, IP schedules, employment rights, media rights, personal philanthropy, causal performance or psychology.','claim_restriction','observed','unreviewed',NULL,'Those domains remain unverified or incomplete.','Absence of public evidence is not evidence of absence.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
